import { afterAll, beforeAll, describe, expect, test } from "bun:test";
import { chmodSync, existsSync, mkdirSync, readFileSync, rmSync, writeFileSync } from "node:fs";
import { dirname, join } from "node:path";
import { recordedInvocations } from "../src/execute";
import { createFixture, sentinelLauncher, type Fixture } from "../src/fixture";
import { writeRecordingWrapper } from "../src/live";
import { cleanupOwnedProcesses, run, SYSTEM_PATH } from "../src/process";

// Executes the hooks and wrapper generated by the real `sentinel integrate factory-droid
// --guard-approved-specs` against Factory Droid 0.243.0, read from the JavaScript bundled in the
// @factory/cli-darwin-arm64@0.243.0 binary and docs.factory.com/reference/hooks-reference:
// - Project hooks load from .factory/hooks.json (falling back to .factory/hooks/hooks.json) and from
//   the `hooks` key of .factory/settings.json. hooks.json holds the events at its top level and is
//   parsed with a schema: events are lists of {matcher?, commandRegex?, hooks: [{type: "command",
//   command, timeout?, preserveRiskLevel?}]}; a file that fails the schema loads no hooks.
// - Commands run through the shell in Droid's working directory, with FACTORY_PROJECT_DIR set.
// - PreToolUse denies with hookSpecificOutput.permissionDecision; exit 2 blocks the tool.
// - PostToolUse and Stop feed stderr to the model on exit 2; Stop continues with decision "block"
//   and sends stop_hook_active on the continuation.
// Tools: Create and Edit take file_path, ApplyPatch takes input (the patch), Execute takes command.
// The real Sentinel answers behind a recording wrapper.

const EVENTS = ["PreToolUse", "PostToolUse", "Notification", "UserPromptSubmit", "Stop", "SubagentStop", "PreCompact", "SessionStart", "SessionEnd"];
const HOOK_FIELDS = ["type", "command", "timeout", "preserveRiskLevel"];

/** Applies Droid's hooks.json schema; returns why the file would load no hooks, or which events it has. */
function droidLoads(json: string): { errors: string[]; events: string[] } {
  let config: any;
  try {
    config = JSON.parse(json);
  } catch {
    return { errors: ["not JSON"], events: [] };
  }
  const errors: string[] = [];
  const events = EVENTS.filter((event) => config[event] !== undefined);
  for (const event of events) {
    if (!Array.isArray(config[event])) {
      errors.push(`${event} is not a list`);
      continue;
    }
    config[event].forEach((group: any, index: number) => {
      if (!Array.isArray(group?.hooks)) return errors.push(`${event}[${index}] has no hooks list`);
      for (const hook of group.hooks) {
        if (hook.type !== "command" || typeof hook.command !== "string") errors.push(`${event}[${index}] hook is not a command`);
        if (hook.timeout !== undefined && typeof hook.timeout !== "number") errors.push(`${event}[${index}] timeout is not a number`);
        for (const key of Object.keys(hook)) if (!HOOK_FIELDS.includes(key)) errors.push(`${event}[${index}] hook has ${key}`);
      }
    });
  }
  return { errors, events: errors.length > 0 ? [] : events };
}

let fixture: Fixture;
let unguarded: Fixture;
let config: any;
let log: string;
let bin: string;

beforeAll(async () => {
  const sentinel = sentinelLauncher(process.env)!;
  fixture = await createFixture({ harness: "factory-droid", guard: true, sentinel });
  unguarded = await createFixture({ harness: "factory-droid", guard: false, sentinel });
  config = JSON.parse(readFileSync(join(fixture.root, ".factory/hooks.json"), "utf8"));
  bin = join(dirname(fixture.root), "sentinel-bin");
  log = join(dirname(fixture.root), "sentinel-log");
  writeRecordingWrapper(bin, log, sentinel);
  for (const f of [fixture, unguarded]) {
    await run(["/usr/bin/git", "init", "-q"], { cwd: f.root, env: f.env, timeoutMs: 30_000 });
    mkdirSync(join(f.root, "src/main/java"), { recursive: true });
  }
  mkdirSync(join(fixture.root, "openspec/specs/auth"), { recursive: true });
  writeFileSync(join(fixture.root, "openspec/specs/auth/spec.md"), "# Auth\n");
  mkdirSync(join(fixture.root, "openspec/changes/add-x"), { recursive: true });
  writeFileSync(join(fixture.root, "openspec/changes/add-x/tasks.md"), "- [ ] 1.1\n");
  writeFileSync(join(fixture.root, "openspec-stub.sh"), '#!/bin/sh\nif [ -f SPEC_FAIL ]; then echo "add-x: missing scenario"; exit 1; fi\n');
  chmodSync(join(fixture.root, "openspec-stub.sh"), 0o755);
  const toml = join(fixture.root, "sentinel.toml");
  writeFileSync(toml, `${readFileSync(toml, "utf8")}\n[quality-gates.openspec]\nenabled = true\ncommand = ["./openspec-stub.sh"]\n`);
});

afterAll(() => {
  fixture?.cleanup();
  unguarded?.cleanup();
  cleanupOwnedProcesses();
});

const hooks = (event: string, tool?: string, cfg = config) =>
  ((cfg[event] ?? []) as any[])
    .filter((group) => tool === undefined || !group.matcher || group.matcher === "*" || new RegExp(group.matcher).test(tool))
    .flatMap((group) => group.hooks);

/** Runs a hook like Droid: through the shell, in its working directory, with the event on stdin. */
async function launch(f: Fixture, hook: any, payload: unknown, cwd = f.root) {
  const before = recordedInvocations(log).length;
  const env = { ...f.env, FACTORY_PROJECT_DIR: cwd, DROID_PROJECT_DIR: cwd, CLAUDE_PROJECT_DIR: cwd, PATH: `${bin}:${SYSTEM_PATH}` };
  const stdin =
    typeof payload === "string"
      ? payload
      : JSON.stringify({ session_id: "s", transcript_path: "t", cwd, permission_mode: "auto-low", ...(payload as object) });
  const result = await run(["/bin/sh", "-c", hook.command], { cwd, env, stdin, timeoutMs: 60_000 });
  return { result, invocations: recordedInvocations(log).slice(before) };
}

const tool = (event: string, name: string, input: Record<string, unknown>, cwd?: string) =>
  launch(fixture, hooks(event, name)[0], { hook_event_name: event, tool_name: name, tool_input: input }, cwd);
const decision = (stdout: string) => JSON.parse(stdout).hookSpecificOutput;

describe("generated hooks against Factory Droid 0.243.0", () => {
  test("Droid discovers the hook file and loads every event", () => {
    expect(existsSync(join(fixture.root, ".factory/hooks.json"))).toBe(true);
    expect(droidLoads(readFileSync(join(fixture.root, ".factory/hooks.json"), "utf8"))).toEqual({
      errors: [],
      events: ["PreToolUse", "PostToolUse", "Stop"],
    });
  });

  test("negative control: the legacy plugin file loads no hooks, even at a discovered path", () => {
    expect(droidLoads(readFileSync(join(import.meta.dir, "legacy-plugin.json.txt"), "utf8"))).toEqual({ errors: [], events: [] });
  });

  test("the guard runs before edits, patches and shell commands; checks after edits and at Stop", () => {
    for (const name of ["Create", "Edit", "MultiEdit", "ApplyPatch", "Execute"]) expect(hooks("PreToolUse", name).length).toBe(1);
    expect(hooks("PreToolUse", "Read").length).toBe(0);
    expect(hooks("PreToolUse", "ExecuteScript").length).toBe(0);
    for (const name of ["Create", "Edit", "ApplyPatch"]) expect(hooks("PostToolUse", name).length).toBe(1);
    expect(hooks("PostToolUse", "Execute").length).toBe(0);
    expect(hooks("Stop").length).toBe(1);
  });

  test("checks get more time than Droid's 60 second default", () => {
    expect(hooks("PostToolUse", "Edit")[0].timeout).toBeGreaterThanOrEqual(300);
    expect(hooks("Stop")[0].timeout).toBeGreaterThanOrEqual(300);
  });

  test("the ownership marker is a shell comment in each command", () => {
    for (const event of ["PreToolUse", "PostToolUse", "Stop"]) {
      for (const h of hooks(event)) expect(h.command).toEndWith("# sentinel-owned: factory-droid-native-hooks v1");
    }
  });
});

describe("hook execution", () => {
  test("the guard denies an edit to an approved spec, from a subdirectory", async () => {
    const { result, invocations } = await tool(
      "PreToolUse",
      "Edit",
      { file_path: join(fixture.root, "openspec/specs/auth/spec.md"), old_str: "# Auth", new_str: "# X" },
      join(fixture.root, "src/main/java"),
    );
    expect(invocations.map((i) => i.argv)).toEqual([["hook", "native", "--agent", "factory-droid", "--guard-approved-specs", "--event-stdin"]]);
    expect(invocations[0].cwd.endsWith("/project")).toBe(true);
    expect(decision(result.stdout)).toMatchObject({ hookEventName: "PreToolUse", permissionDecision: "deny" });
    expect(decision(result.stdout).permissionDecisionReason).toContain("openspec/specs/auth/spec.md");
  });

  test("the guard denies a patch to an approved spec and allows one to an active change", async () => {
    const patch = (path: string) => `*** Begin Patch\n*** Update File: ${path}\n@@\n-old\n+new\n*** End Patch\n`;
    const denied = await tool("PreToolUse", "ApplyPatch", { input: patch("openspec/specs/auth/spec.md") });
    expect(decision(denied.result.stdout).permissionDecision).toBe("deny");
    const allowed = await tool("PreToolUse", "ApplyPatch", { input: patch("openspec/changes/add-x/tasks.md") });
    expect([allowed.result.exitCode, allowed.result.stdout.trim()]).toEqual([0, ""]);
  });

  test("the guard denies a protected shell command and passes a harmless one", async () => {
    const denied = await tool("PreToolUse", "Execute", { command: "rm openspec/specs/auth/spec.md" });
    expect(decision(denied.result.stdout).permissionDecision).toBe("deny");
    const allowed = await tool("PreToolUse", "Execute", { command: "ls src" });
    expect([allowed.result.exitCode, allowed.result.stdout.trim()]).toEqual([0, ""]);
  });

  test("uninspectable input is denied", async () => {
    const { result } = await launch(fixture, hooks("PreToolUse", "Execute")[0], "{not json");
    expect(decision(result.stdout).permissionDecision).toBe("deny");
  });

  test("a failing check after an edit exits 2 with the findings on stderr", async () => {
    writeFileSync(join(fixture.root, "FAIL"), "");
    try {
      const { result, invocations } = await tool("PostToolUse", "Create", { file_path: "src/main/java/A.java", content: "" });
      expect(invocations.map((i) => i.argv)).toEqual([["hook", "native", "--agent", "factory-droid", "--event-stdin"]]);
      expect(result.exitCode).toBe(2);
      expect(result.stderr).toContain("Sentinel quality findings");
    } finally {
      rmSync(join(fixture.root, "FAIL"), { force: true });
    }
  });

  test("a clean edit is silent", async () => {
    const { result } = await tool("PostToolUse", "Edit", { file_path: "src/main/java/A.java" });
    expect([result.exitCode, result.stdout.trim()]).toEqual([0, ""]);
  });

  test("Stop findings continue the turn once with decision block, then only report", async () => {
    writeFileSync(join(fixture.root, "SPEC_FAIL"), "");
    try {
      const stop = (active: boolean) =>
        launch(fixture, hooks("Stop")[0], { hook_event_name: "Stop", stop_hook_active: active, tool_execution_count: 0, elapsed_time: 1 });
      const first = await stop(false);
      expect(first.result.exitCode).toBe(0);
      expect(JSON.parse(first.result.stdout)).toMatchObject({ decision: "block" });
      expect(JSON.parse(first.result.stdout).reason).toContain("missing scenario");
      const second = await stop(true);
      expect([second.result.exitCode, second.result.stdout.trim()]).toEqual([0, ""]);
      expect(second.result.stderr).toContain("missing scenario");
    } finally {
      rmSync(join(fixture.root, "SPEC_FAIL"), { force: true });
    }
  });

  test("with the guard disabled, the pre phase allows without running Sentinel", async () => {
    const unguardedConfig = JSON.parse(readFileSync(join(unguarded.root, ".factory/hooks.json"), "utf8"));
    const { result, invocations } = await launch(unguarded, hooks("PreToolUse", "Execute", unguardedConfig)[0], {
      hook_event_name: "PreToolUse",
      tool_name: "Execute",
      tool_input: { command: "rm openspec/specs/auth/spec.md" },
    });
    expect([result.exitCode, result.stdout.trim(), invocations.length]).toEqual([0, "", 0]);
  });
});
